    float length,
    int width_cells_,
    bool side_exit,
    char* texture_a,
    char* texture_b,
    char* cap_texture)
{
    kind = PATH_TEMPLATE_KIND_START;
    is_mirrored_x = 0;
    side_exit_mode = 0;
